// Generated by scripts/generate-operation-tests.js. Do not edit.
// Generated tests keep their order. Any other .test.js file in this folder
// is discovered automatically, so manual tests need no config changes.
const fs = require('fs');
const path = require('path');

const generated = [
  'get-user-by-userid-account-type.test.js',
  'get-user-by-userid.test.js',
  'get-user-settings.test.js',
  'get-user.test.js',
  'patch-user-2fa-toggle.test.js',
  'patch-user-by-userid-next-step.test.js',
  'patch-user-by-userid-status.test.js',
  'post-user-by-id-reset-pin.test.js',
  'post-user-by-id-suspend.test.js',
  'post-user-by-id-unlock.test.js',
  'post-user-by-id-unsuspend.test.js',
  'post-user-change-password-confirm.test.js',
  'post-user-change-password-initiate.test.js',
  'post-user-create-users.test.js',
  'post-user-profile-picture.test.js',
];

function collectTests(directory) {
  return fs.readdirSync(directory, { withFileTypes: true }).flatMap(entry => {
    const fullPath = path.join(directory, entry.name);
    if (entry.isDirectory()) {
      return collectTests(fullPath);
    }
    if (entry.isFile() && entry.name.endsWith('.test.js') && entry.name !== 'run-tests-in-order.test.js') {
      return [path.relative(__dirname, fullPath).split(path.sep).join("/")];
    }
    return [];
  });
}

const available = collectTests(__dirname);

const ordered = [
  ...generated.filter(name => available.includes(name)),
  ...available.filter(name => !generated.includes(name)).sort()
];

module.exports = {
  testOrder: ordered.map(name => `./${name}`)
};
